                _validate_trans_expression(name, var, parser, lineno=lineno)
    def _validate_trans_expression(name: str, expr: nodes.Expr, parser: "Parser", lineno: int) -> None:
        if isinstance(expr, nodes.Const) or isinstance(expr, nodes.Name) or isinstance(expr, nodes.Call) or isinstance(expr, nodes.Getattr) or isinstance(expr, nodes.Filter) or isinstance(expr, nodes.Test):
            return
        parser.fail(f"Invalid expression type: {expr!r}", lineno=lineno)
    _validate_trans_variables(variables, parser, lineno)

